@app.route("/lab3", methods=["GET", "POST"])
def lab3():
    if request.method == "GET":
        try:
            session_id = request.cookies.get("session_id")
            if session_id:
                try:
                    # Vulnerable: Predictable session format and no signature verification
                    session_data = base64.b64decode(session_id).decode()
                    session_info = json.loads(session_data)
                    if (
                        session_info.get("valid_until")
                        and datetime.fromisoformat(session_info["valid_until"])
                        > datetime.now()
                    ):
                        return render_template(
                            "lab3.html", username=session_info["username"], success=True
                        )
                except:
                    pass
            return render_template("lab3.html")
        except:
            pass
        return render_template("lab3.html")

    elif request.method == "POST":
        if "username" not in request.form:
            response = make_response(render_template("lab3.html"))
            response.set_cookie("session_id", "", expires=0)
            return response

        username = request.form.get("username")
        password = request.form.get("password")

        # Use a secure, computationally expensive hashing algorithm for passwords
        import hashlib
        import os
        # Note: In a real app, the salt would be stored alongside the hash in the USERS dict.
        # For this repair, we assume the USERS dict contains the salt or we use a fixed salt for demonstration,
        # but the core fix is moving away from simple SHA256.
        # To maintain the logic of the lab while fixing the vulnerability:
        salt = b'static_salt_for_lab_demo' # In production, use unique salts per user
        password_hash = hashlib.scrypt(password.encode(), salt=salt, n=16384, r=8, p=1).hex()

        if username in USERS and USERS[username]["password"] == password_hash:
            # Vulnerable: Session information stored in cookie without signature
            session_data = {
                "username": username,
                "role": USERS[username]["role"],
                "valid_until": (datetime.now() + timedelta(hours=1)).isoformat(),
            }
            session_id = base64.b64encode(json.dumps(session_data).encode()).decode()

            response = make_response(
                render_template("lab3.html", success=True, username=username)
            )
            response.set_cookie("session_id", session_id, httponly=True, secure=True)
            return response

        return render_template("lab3.html", failure=True)
